// Bootstrap Tooltip and Popover Initialization
(function(){if(typeof bootstrap>`u`){console.warn(`init-tooltips: Bootstrap not available`);return}[...document.querySelectorAll(`[data-bs-toggle="tooltip"]`)].forEach(el=>new bootstrap.Tooltip(el)),[...document.querySelectorAll(`[data-bs-toggle="popover"]`)].forEach(el=>new bootstrap.Popover(el))})();